  function authUI(){var s=session();$$('[data-auth-guest]').forEach(function(e){e.classList.toggle('hidden',!!s)});$$('[data-auth-user]').forEach(function(e){e.classList.toggle('hidden',!s)});if(s){$$('[data-auth-name]').forEach(function(e){e.textContent=s.first||'Driver'});$$('[data-auth-email]').forEach(function(e){e.textContent=s.email||''});$$('[data-auth-initial]').forEach(function(e){e.textContent=(s.first||'D').charAt(0).toUpperCase()})}}
  function login(){var f=$('#login-form');if(!f)return;f.addEventListener('submit',function(e){e.preventDefault();var d=Object.fromEntries(new FormData(f));var u=read(K.users,[]).find(function(x){return x.email.toLowerCase()===String(d.email).toLowerCase()&&x.password===d.password});var st=$('#auth-status');if(!u){st.className='status-box error';st.textContent='Email or password is incorrect.';return}var payload={id:u.id,first:u.first,last:u.last,email:u.email,phone:u.phone};storageRemove('local',K.session);storageRemove('session',K.session);if(d.remember){write(K.session,payload)}else{storageSet('session',K.session,JSON.stringify(payload))}st.className='status-box success';st.textContent='Signed in successfully. Opening your profile…';setTimeout(function(){location.href='profile.html'},500)})}
  function register(){var f=$('#register-form');if(!f)return;f.addEventListener('submit',function(e){e.preventDefault();var d=Object.fromEntries(new FormData(f));var st=$('#auth-status');if(String(d.password||'').length<8){st.className='status-box error';st.textContent='Password must contain at least 8 characters.';return}var u=read(K.users,[]);if(u.some(function(x){return x.email.toLowerCase()===String(d.email).toLowerCase()})){st.className='status-box error';st.textContent='This email already has an account.';return}var n={id:'u'+Date.now(),first:d.first,last:d.last,email:d.email,phone:d.phone,password:d.password};u.push(n);write(K.users,u);write(K.session,{id:n.id,first:n.first,last:n.last,email:n.email,phone:n.phone});st.className='status-box success';st.textContent='Account created. Opening your profile…';setTimeout(function(){location.href='profile.html'},500)})}
  function bookingRef(){return 'AT-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,5).toUpperCase()}
  function paymentInfo(d,sd){var amount=Number(sd.price||0),method=d.paymentMethod||'pay_later',label='Pay at Workshop',detail='',status='Pending';if(amount<=0){method='pay_later';label='No payment required';detail='Free service';status='No payment due'}else if(method==='upi'){label='UPI';detail=d.upiId?('UPI · '+d.upiId):'UPI';status='Demo payment details saved'}else if(method==='card'){var last=String(d.cardNumber||'').replace(/\D/g,'').slice(-4);label='Credit / Debit Card';detail=last?('Card ending '+last):'Card';status='Demo payment details saved'}return {method:method,label:label,detail:detail,status:status,amount:amount,reference:(method==='pay_later'||amount<=0)?'':('PAY-'+Date.now().toString(36).toUpperCase())}}
  function makeBooking(d,source){var sd=SERVICES[d.service]||SERVICES.inspection,p=paymentInfo(d,sd);return {id:bookingRef(),reference:null,userId:session()?session().id:null,email:d.email,name:d.name,phone:d.phone,vehicle:d.vehicle||d.reg||'',service:d.service,serviceName:sd.name,date:d.date,time:d.time||'',method:d.method==='pickup'?'Pickup & delivery':'Workshop handover',pickupAddress:d.pickupAddress||d.address||'',deliveryAddress:d.deliveryAddress||d.pickupAddress||d.address||'',address:d.pickupAddress||d.address||'',notes:d.notes||'',amount:p.amount,paymentMethod:p.method,paymentLabel:p.label,paymentDetail:p.detail,paymentStatus:p.status,paymentReference:p.reference,status:'Requested',createdAt:new Date().toISOString(),source:source||(session()?'account':'guest')}}
  function persistBooking(item){item.reference=item.id;var all=read(K.bookings,[]);all.push(item);write(K.bookings,all);storageSet('local',K.lastBooking,item.id);return item}
  function successPopup(item){var old=$('#booking-success-modal');if(old)old.remove();var el=document.createElement('div');el.id='booking-success-modal';el.className='booking-overlay';var amount=item.amount?('₹'+Number(item.amount).toLocaleString('en-IN')):'Free';var pay=item.paymentLabel||'Pay at Workshop';el.innerHTML='<div class="booking-dialog booking-success" role="dialog" aria-modal="true" aria-labelledby="booking-success-title"><button class="booking-x" type="button" data-close-booking-success aria-label="Close">×</button><div class="success-mark">✓</div><h2 id="booking-success-title">Booking successful</h2><p>Your booking reference is <strong>'+esc(item.id)+'</strong>.</p><p class="booking-summary">'+esc(item.serviceName)+' · '+esc(item.date)+(item.time?' · '+esc(item.time):'')+'</p><p class="booking-summary"><strong>Payment:</strong> '+esc(pay)+' · '+esc(amount)+(item.paymentDetail?' · '+esc(item.paymentDetail):'')+'</p><p class="booking-summary"><strong>Payment status:</strong> '+esc(item.paymentStatus||'Pending')+'</p>'+(item.paymentReference?'<p class="booking-summary"><strong>Payment ref:</strong> '+esc(item.paymentReference)+' <span style="color:var(--muted)">(demo only)</span></p>':'')+'<div class="booking-actions"><button class="btn-primary" type="button" data-book-another>Book another service</button><button class="btn-ghost" type="button" data-close-booking-success>Close</button></div></div>';document.body.appendChild(el);document.body.classList.add('modal-open');setTimeout(function(){var close=$('[data-close-booking-success]',el);if(close)close.focus()},0);}
  function setFieldState(field,active,clearWhenHidden){if(!field)return;field.required=!!active;field.disabled=!active;if(!active&&clearWhenHidden)field.value=''}
