  function tyreSearch(){
    var input=$('#tyre-product-search');
    var grid=$('[data-tyre-grid]');
    if(!input||!grid)return;
    var cards=$$('.tyre-product-card',grid);
    var count=$('[data-tyre-result-count]');
    var status=$('#tyre-search-status');
    var empty=$('[data-tyre-empty]');
    var clear=$('[data-tyre-search-clear]');
    function apply(){
      var q=String(input.value||'').trim().toLowerCase();
      var shown=0;
      cards.forEach(function(card){
        var hay=(card.textContent||'').replace(/\s+/g,' ').toLowerCase();
        var match=!q||hay.indexOf(q)>-1;
        card.hidden=!match;
        card.classList.toggle('tyre-search-hidden',!match);
        if(match)shown++;
      });
      if(count)count.textContent=String(shown);
      if(status)status.lastChild && (status.lastChild.textContent=shown===1?' tyre available':' tyres available');
      if(empty)empty.hidden=shown!==0;
      if(clear)clear.classList.toggle('is-visible',!!q);
    }
    input.addEventListener('input',apply);
    input.addEventListener('search',apply);
    if(clear)clear.addEventListener('click',function(){input.value='';apply();input.focus()});
    apply();
  }

  function setupFilterToggles(){$$('[data-filter-toggle]').forEach(function(btn){var id=btn.getAttribute('data-filter-toggle'),panel=id&&document.getElementById(id);if(!panel)return;function set(open){panel.classList.toggle('filter-panel-collapsed',!open);btn.setAttribute('aria-expanded',open?'true':'false');btn.classList.toggle('active',open)}btn.addEventListener('click',function(){set(btn.getAttribute('aria-expanded')!=='true')});set(btn.getAttribute('aria-expanded')!=='false')})}
  function brandFilter(){var cards=$$('[data-brand-card]');if(!cards.length)return;var tier='all',input=$('#brand-search'),status=$('#brand-filter-status'),buttons=$$('[data-brand-filter]');function run(){var q=(input?input.value:'').trim().toLowerCase(),shown=0;cards.forEach(function(c){var ok=(tier==='all'||c.dataset.tier===tier)&&(!q||c.textContent.toLowerCase().includes(q));c.classList.toggle('hidden',!ok);if(ok)shown++});if(status)status.textContent=shown+' brand'+(shown===1?'':'s')+' shown'}buttons.forEach(function(b){b.addEventListener('click',function(){tier=b.dataset.brandFilter;buttons.forEach(function(x){x.classList.toggle('active',x===b)});run()})});if(input)input.addEventListener('input',run);run()}
  function enhanceTyreFilters(){var cards=$$('.tyre-product-card'),buttons=$$('[data-tyre-tier-filter]'),input=$('#tyre-product-search');if(!cards.length||!buttons.length)return;var tier='all',count=$('[data-tyre-result-count]'),status=$('#tyre-search-status'),empty=$('[data-tyre-empty]');function run(){var q=(input?input.value:'').trim().toLowerCase(),shown=0;cards.forEach(function(c){var okTier=tier==='all'||c.dataset.tier===tier,okQ=!q||c.textContent.toLowerCase().includes(q),ok=okTier&&okQ;c.hidden=!ok;c.classList.toggle('tyre-search-hidden',!ok);if(ok)shown++});if(count)count.textContent=shown;if(status&&status.lastChild)status.lastChild.textContent=shown===1?' tyre available':' tyres available';if(empty)empty.hidden=shown!==0}buttons.forEach(function(b){b.addEventListener('click',function(){tier=b.dataset.tyreTierFilter;buttons.forEach(function(x){x.classList.toggle('active',x===b)});run()})});if(input)input.addEventListener('input',run);run()}
